options.customCss:
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&family=Newsreader:ital,wght@0,500;0,600;0,700&display=swap');

:root {
  /* Tipografía: IBM Plex Sans para texto general (afecta cuerpo, labels,
     inputs y botón, que ya usan var(--font-family) en la plantilla base) */
  --font-family: 'IBM Plex Sans', 'Open Sans', sans-serif;

  /* Fondo claro */
  --color-background: #f4f6fb;

  /* Azul institucional: encabezado del formulario y botón de envío */
  --color-header: #123a6b;
  --color-submit-btn-bg: #123a6b;
  --color-submit-btn-text: #ffffff;

  /* Texto de la descripción del formulario: gris azulado legible, no el
     acento naranja (reservado para foco/franja/detalles) */
  --color-link: #3d4f68;
  --color-label: #22344a;
  --color-input-text: #1f2937;
  --color-input-bg: #ffffff;
  --color-input-border: #d7dde6;

  /* Foco: NO se usa el naranja institucional puro (#e8781f) tal cual.
     Verificado con la fórmula de luminancia relativa de WCAG 2.1:
     #e8781f contra blanco da 2.94:1, por debajo del mínimo 3:1 exigido
     por el criterio 1.4.11 (Non-text Contrast) para indicadores de estado
     de componentes de interfaz como el foco. Se usa una variante
     oscurecida de la misma familia de naranja (#c15f12, 4.27:1) que sí
     cumple AA, manteniendo el naranja puro como acento decorativo en la
     franja superior y el pie de página. */
  --color-focus-border: #c15f12;

  /* Marca de campo obligatorio: naranja institucional puro (elemento
     decorativo junto al label, no es un indicador de estado de foco, así
     que el umbral de 1.4.11 no aplica igual) */
  --color-required: #e8781f;

  /* Tarjeta: esquinas más redondeadas y sombra suave con tinte azulado */
  --border-radius-card: 16px;
  --border-radius-input: 8px;
  --color-card-shadow: rgba(18, 58, 107, 0.1);
  --box-shadow-card: 0px 8px 28px 0px var(--color-card-shadow);

  /* Enlaces dentro de bloques HTML (ej. el aviso LOPDP) */
  --color-html-text: #33455e;
  --color-html-link: #123a6b;
}

/* Títulos con Newsreader (tipografía distinta a la del cuerpo) */
.form-header h1 {
  font-family: 'Newsreader', serif;
  font-weight: 600;
}

/* Franja superior naranja: acento decorativo, no un indicador de estado,
   por eso puede usar el naranja institucional puro sin ajustar contraste.
   body ya es display:flex; flex-direction:column en la plantilla base,
   así que este ::before se inserta como primer elemento del flujo, antes
   de .container, sin necesidad de position:fixed ni compensar con padding. */
body::before {
  content: '';
  display: block;
  width: 100%;
  height: 6px;
  flex-shrink: 0;
  background: #e8781f;
}

/* Hover del botón: azul más oscuro, en vez de la opacidad 0.7 por
   defecto de n8n (por eso se restablece opacity:1 explícitamente) */
#submit-btn:hover {
  background-color: #0d2c52;
  opacity: 1;
}

/* Bordes de foco con contraste AA verificado (ver --color-focus-border) */
form textarea:focus,
form input:focus {
  outline: none;
  border-width: 2px;
  border-color: var(--color-focus-border);
}
.select-input:focus-within {
  border-width: 2px;
  border-color: var(--color-focus-border);
}

/* Bloque informativo LOPDP (elemento "Custom HTML" antes del
   consentimiento): se apoya en las reglas reales que n8n aplica a
   div.html (párrafos, enlaces) en la plantilla base */
div.html {
  background: #f0f4fa;
  border: 1px solid #d7dde6;
  border-left: 3px solid #e8781f;
  border-radius: 8px;
  padding: 14px 16px;
  margin-bottom: 16px;
}
div.html a {
  font-weight: 600;
}

/* Pie institucional: .container siempre está presente en la plantilla
   base, así que ::after es un punto de anclaje seguro sin depender de
   ninguna clase interna del formulario */
.container::after {
  content: 'Desarrollado por Larissa Danahe Guamán Salazar · Trabajo de titulación 2026 · Instituto Superior Tecnológico de Turismo y Patrimonio Yavirac';
  display: block;
  margin-top: 28px;
  padding-top: 16px;
  border-top: 1px solid #dbe2ea;
  font-size: 11px;
  line-height: 1.5;
  color: #7b8794;
  text-align: center;
}

/* Responsivo: n8n ya vuelve la tarjeta de borde a borde bajo 500px (ver
   su propio @media en la plantilla base); solo se ajustan detalles
   propios para que sigan siendo legibles en pantallas pequeñas */
@media only screen and (max-width: 500px) {
  body::before {
    height: 4px;
  }
  .container::after {
    font-size: 10px;
    padding-left: 16px;
    padding-right: 16px;
  }
}

parameters.jsCode:
// Valida que el archivo subido en el formulario sea un PDF de menos de
// 5MB, y registra la marca de tiempo de consentimiento LOPDP exigida por la
// Ley Orgánica de Protección de Datos Personales del Ecuador. Se hacen
// ambas cosas en un solo nodo Code para no depender de si un nodo Set
// preserva o no los datos binarios del archivo entre pasos.
//
// NOTA: este nodo corre en modo "Run Once for Each Item"
// (mode: 'runOnceForEachItem'), que espera que "return" entregue UN SOLO
// OBJETO ITEM ({ json: {...} }), NO un arreglo. Ver la nota equivalente en
// el nodo "Validar y Calcular Score".

const TAMANO_MAXIMO_BYTES = 5 * 1024 * 1024; // 5 MB

// NOTA: "CV" es el nombre esperado del binary property que genera el campo
// de archivo del Form Trigger. Si al probar el formulario n8n usa otro
// nombre (visible en la pestaña "Binary" de la salida de este nodo),
// ajustar la clave "CV" aquí abajo.
const binario = $input.item.binary && $input.item.binary.CV;

let archivoValido = true;
let archivoMotivoRechazo = null;

if (!binario) {
  archivoValido = false;
  archivoMotivoRechazo = 'No se recibió ningún archivo en el campo de CV.';
} else if (binario.mimeType !== 'application/pdf') {
  archivoValido = false;
  archivoMotivoRechazo = `El archivo debe ser PDF. Se recibió: ${binario.mimeType}`;
} else {
  // CORRECCIÓN VERIFICADA: "binary.CV.fileSize" NO es un número de bytes:
  // es texto ya formateado para humanos (ej. "8.11 MB"), generado por la
  // librería "pretty-bytes" que usa n8n internamente (confirmado leyendo
  // n8n-core/dist/binary-data/binary-data.service.js dentro del
  // contenedor: "binaryData.fileSize = prettyBytes(size)"). Number("8.11
  // MB") da NaN, que con "|| 0" caía en silencio a 0, así que la
  // validación de tamaño nunca se disparaba -confirmado subiendo un PDF
  // de 8.11 MB que pasó como válido pese al límite de 5 MB-. Ese mismo
  // código de n8n guarda, en el mismo objeto binario, el número real de
  // bytes sin formatear en "binary.CV.bytes" ("binaryData.bytes = size"),
  // que es el campo correcto para comparar contra TAMANO_MAXIMO_BYTES.
  const tamanoBytes = typeof binario.bytes === 'number' ? binario.bytes : 0;
  if (tamanoBytes > TAMANO_MAXIMO_BYTES) {
    archivoValido = false;
    archivoMotivoRechazo = `El archivo pesa ${(tamanoBytes / 1024 / 1024).toFixed(2)} MB, supera el máximo de 5 MB.`;
  }
}

return {
  json: {
    ...$input.item.json,
    archivo_valido: archivoValido,
    archivo_motivo_rechazo: archivoMotivoRechazo,
    consentimiento_lopdp_timestamp: new Date().toISOString(),
    consentimiento_lopdp_aceptado: $input.item.json['Consentimiento LOPDP'] === 'Acepto'
  },
  binary: $input.item.binary
};

// El candidato NO aceptó el tratamiento de datos personales
// ("Consentimiento LOPDP" = "No acepto"). Bajo la Ley Orgánica de
// Protección de Datos Personales del Ecuador, el consentimiento es la
// PRECONDICIÓN para el tratamiento, no un dato más a registrar junto a
// los demás: por eso esta rama existe ANTES de validar el archivo, antes
// de llamar a la IA y antes de escribir nada en la base de datos de
// candidatos de Notion. Este nodo solo prepara el correo de aviso; el
// email del candidato viaja en memoria únicamente para poder informarle
// que su postulación no se procesó (uso mínimo, para responder a su
// propia solicitud), pero NUNCA se persiste en Notion.
//
// NOTA: este nodo corre en modo "Run Once for Each Item"
// (mode: 'runOnceForEachItem'), que espera que "return" entregue UN SOLO
// OBJETO ITEM ({ json: {...} }), NO un arreglo. Ver la nota equivalente en
// el nodo "Validar y Calcular Score".

const datos = $input.item.json;

return {
  json: {
    estado: 'consentimiento_rechazado',
    nombre: datos['Nombre completo'] || null,
    email: datos['Correo electrónico'] || null,
    puesto: datos['Puesto al que postula'] || null,
    consentimiento_lopdp_timestamp: datos.consentimiento_lopdp_timestamp,
    consentimiento_lopdp_aceptado: false
  }
};

// ============================================================================
// NODO GENERADO AUTOMÁTICAMENTE por scripts/generar-workflow.js
// Contenido de src/extraer-respuesta-ia.js, src/validacion.js y
// src/scoring.js embebido tal cual, más la orquestación específica de este
// workflow al final. NO editar a mano: los cambios se pierden al
// regenerar. Editar los archivos fuente en su lugar.
// ============================================================================

/**
 * ============================================================================
 * EXTRACCIÓN DEL TEXTO ÚTIL DE LA RESPUESTA CRUDA DE UN PROVEEDOR DE IA
 * ============================================================================
 *
 * Sistema Inteligente de Reclutamiento Predictivo - Trabajo de titulación.
 *
 * El workflow llama a la API del proveedor de IA con un nodo httpRequest
 * genérico (ver README, "Por qué httpRequest en vez del nodo de Gemini"),
 * no con un nodo propietario que ya sepa interpretar la respuesta. Eso
 * significa que la respuesta llega TAL CUAL la devolvió la API HTTP, con
 * el "sobre" propio de cada proveedor alrededor del texto que realmente
 * interesa (el JSON de extracción generado por el modelo).
 *
 * Gemini, por ejemplo, NO devuelve el JSON de extracción directamente en la
 * raíz de la respuesta: lo devuelve como un STRING anidado en
 * candidates[0].content.parts[0].text. Si esa respuesta completa se le
 * pasara tal cual a validarExtraccion() (src/validacion.js), esta la
 * trataría como un objeto ya parseado, no encontraría "datos_identidad" ni
 * "datos_evaluables" en la raíz, y "repararía" silenciosamente a un objeto
 * con todos los campos en null (ver separarBloques() en validacion.js). El
 * candidato terminaría con score 0 SIN ningún error visible: un fallo
 * silencioso, el peor tipo de bug en un sistema que se presenta ante un
 * tribunal como auditable.
 *
 * Esta función es la única responsable de "pelar" ese sobre específico de
 * cada proveedor y devolver el texto plano, o explicar por qué no pudo.
 * Migrar de proveedor (Gemini -> Ollama -> OpenAI -> Claude) implica
 * agregar un caso aquí, no tocar el nodo de n8n ni el resto del pipeline.
 *
 * Compatible con el nodo "Code" de n8n: sin dependencias externas, se
 * puede pegar tal cual (sin el bloque de exportación de Node) dentro de un
 * nodo Code y llamar a extraerTextoIA(...) con la respuesta del nodo
 * httpRequest.
 * ============================================================================
 */

/**
 * Extrae el texto plano (que debería ser el JSON de extracción) de la
 * respuesta cruda de un proveedor de IA, sin asumir su forma en ningún
 * punto: cada acceso a una propiedad anidada se valida antes de usarse, y
 * cualquier forma inesperada devuelve ok:false con un motivo explicable en
 * vez de lanzar una excepción o devolver basura silenciosamente.
 *
 * @param {*} respuestaCruda - el body de la respuesta HTTP del proveedor,
 *   tal como lo entrega el nodo httpRequest de n8n (ya parseado a objeto).
 * @param {string} proveedor - 'gemini' | 'ollama' | ... (ver config/ia.json)
 * @returns {{ok: true, texto: string} | {ok: false, motivo: string}}
 */
function extraerTextoIA(respuestaCruda, proveedor) {
  if (!respuestaCruda || typeof respuestaCruda !== 'object') {
    return {
      ok: false,
      motivo: `La respuesta de la IA está vacía o no es un objeto (proveedor: "${proveedor}").`
    };
  }

  switch (proveedor) {
    case 'gemini':
      return extraerTextoGemini(respuestaCruda);
    case 'ollama':
      return extraerTextoOllama(respuestaCruda);
    default:
      return {
        ok: false,
        motivo: `Proveedor de IA no reconocido: "${proveedor}". Revisar config/ia.json y agregar ` +
          'un caso en extraerTextoIA() para este proveedor si es nuevo.'
      };
  }
}

/**
 * Mapeo para Gemini (API "generateContent" de Generative Language API).
 * Forma esperada de una respuesta exitosa:
 *
 *   {
 *     "candidates": [{
 *       "content": { "parts": [{ "text": "..." }], "role": "model" },
 *       "finishReason": "STOP",
 *       ...
 *     }],
 *     ...
 *   }
 *
 * Y de una respuesta con error:
 *
 *   { "error": { "code": 400, "message": "...", "status": "..." } }
 *
 * Se valida cada nivel de anidamiento por separado (nunca se asume que
 * existe) y se distinguen explícitamente tres formas de fallo:
 *   1. La API devolvió un error (campo "error" presente).
 *   2. La respuesta no tiene la forma esperada (candidates[0] ausente, o
 *      content.parts[0].text ausente).
 *   3. La generación no terminó normalmente (finishReason !== "STOP"),
 *      ej. la respuesta fue truncada por límite de tokens o bloqueada por
 *      políticas de contenido (SAFETY, RECITATION, etc.). Un texto
 *      truncado casi seguro no es JSON válido, así que ni se intenta usar.
 *
 * @param {object} respuesta
 * @returns {{ok: true, texto: string} | {ok: false, motivo: string}}
 */
function extraerTextoGemini(respuesta) {
  if (respuesta.error) {
    const mensaje =
      (respuesta.error && typeof respuesta.error === 'object' && respuesta.error.message) ||
      JSON.stringify(respuesta.error);
    return { ok: false, motivo: `La API de Gemini devolvió un error: ${mensaje}` };
  }

  const candidatos = Array.isArray(respuesta.candidates) ? respuesta.candidates : null;
  const primerCandidato = candidatos && candidatos[0];

  if (!primerCandidato) {
    return {
      ok: false,
      motivo: 'La respuesta de Gemini no incluye "candidates[0]". Puede que el prompt haya sido ' +
        'bloqueado antes de generar (revisar "promptFeedback" en la respuesta completa).'
    };
  }

  if (primerCandidato.finishReason && primerCandidato.finishReason !== 'STOP') {
    return {
      ok: false,
      motivo: `Gemini no completó la generación normalmente (finishReason: "${primerCandidato.finishReason}"). ` +
        'La respuesta probablemente está truncada (límite de tokens) o fue bloqueada por políticas ' +
        'de contenido; no se intenta interpretar como JSON.'
    };
  }

  const partes = primerCandidato.content && primerCandidato.content.parts;
  const texto = Array.isArray(partes) && partes[0] ? partes[0].text : undefined;

  if (typeof texto !== 'string' || texto.length === 0) {
    return {
      ok: false,
      motivo: 'No se encontró "candidates[0].content.parts[0].text" en la respuesta de Gemini, o ' +
        'está vacío.'
    };
  }

  return { ok: true, texto };
}

/**
 * Mapeo para Ollama — DOCUMENTADO, NO IMPLEMENTADO todavía (ver README,
 * "Migrar a Ollama"). Se deja como referencia para cuando se active ese
 * proveedor, en vez de adivinar un mapeo sin poder probarlo contra un
 * servidor Ollama real.
 *
 * Ollama expone dos endpoints con formas de respuesta DISTINTAS, y hay que
 * elegir uno al migrar:
 *
 *   - POST /api/generate (con "stream": false) devuelve:
 *       { "model": "...", "response": "<texto>", "done": true, ... }
 *     El texto útil estaría en respuesta.response.
 *
 *   - POST /api/chat (con "stream": false) devuelve:
 *       { "model": "...", "message": { "role": "assistant", "content": "<texto>" },
 *         "done": true, ... }
 *     El texto útil estaría en respuesta.message.content.
 *
 * Al migrar: implementar esta función siguiendo el mismo patrón defensivo
 * que extraerTextoGemini() (validar cada nivel de anidamiento, revisar
 * "done" en vez de "finishReason" para detectar generación incompleta), y
 * quitar el early-return de "no implementado".
 *
 * @param {object} _respuesta
 * @returns {{ok: false, motivo: string}}
 */
function extraerTextoOllama(_respuesta) {
  return {
    ok: false,
    motivo: 'Proveedor "ollama" está documentado pero no implementado en extraerTextoIA() ' +
      '(ver el comentario de extraerTextoOllama en src/extraer-respuesta-ia.js). Implementar ' +
      'antes de usar proveedor:"ollama" en config/ia.json.'
  };
}

// ----------------------------------------------------------------------------
// Exportación
// ----------------------------------------------------------------------------
// Ver la nota equivalente en src/scoring.js: este bloque es inofensivo si se
// pega el archivo dentro de un nodo Code de n8n.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    extraerTextoIA,
    extraerTextoGemini,
    extraerTextoOllama
  };
}


/**
 * ============================================================================
 * CAPA DE VALIDACIÓN DE LA EXTRACCIÓN DE IA
 * ============================================================================
 *
 * Sistema Inteligente de Reclutamiento Predictivo - Trabajo de titulación.
 *
 * El nodo de IA (ver src/prompt-extraccion.md) devuelve texto que DEBERÍA
 * ser JSON estricto con la forma:
 *
 *   {
 *     "datos_identidad": { "nombre": ..., "email": ..., "telefono": ... },
 *     "datos_evaluables": { "anios_experiencia": ..., "skills_tecnicas": ...,
 *                            "idiomas": ..., "nivel_educativo": ... },
 *     "datos_contexto": { "resumen_profesional": ... }
 *   }
 *
 * "datos_contexto" existe separado de "datos_evaluables" porque
 * resumen_profesional es texto libre: puede contener nombre, edad o
 * marcas de género sin que el NOMBRE del campo lo delate. Por eso nunca se
 * mezcla con los datos que llegan al motor de scoring (ver
 * src/scoring.js, sección "POR QUÉ EXISTE datos_contexto").
 *
 * Pero un LLM es no determinista y puede fallar de muchas formas: texto que
 * no es JSON válido, markdown con ```json envolviendo la respuesta, campos
 * con tipos incorrectos (ej. "anios_experiencia": "5 años" en vez de 5),
 * campos faltantes, o incluso ignorar la estructura anidada y devolver un
 * objeto plano. Este archivo es la ÚNICA puerta de entrada entre "lo que
 * dijo la IA" y "lo que el resto del sistema puede confiar que existe".
 *
 * REGLA DE ORO DEL PIPELINE: el motor de scoring (src/scoring.js) NUNCA debe
 * ejecutarse con datos que no hayan pasado por validarExtraccion() y cuyo
 * resultado tenga valido === true. En el workflow de n8n, el nodo Code que
 * llama a esta función debe verificar "valido" y, si es false, enrutar el
 * candidato a la rama de revisión manual en vez de intentar calcular un
 * score con datos no confiables (ver README.md, sección "Manejo de errores").
 *
 * QUÉ HACE ESTA CAPA (y qué NO hace):
 *   - SÍ: verifica que la salida sea JSON parseable.
 *   - SÍ: normaliza tipos (texto -> número, string suelto -> arreglo, etc.).
 *   - SÍ: rellena con null los campos ausentes o irreconocibles, en vez de
 *     lanzar una excepción (una postulación incompleta debe poder seguir
 *     el flujo hasta revisión manual, no romper el workflow).
 *   - SÍ: repara automáticamente el caso común en que la IA devuelve un
 *     objeto plano en lugar de la estructura anidada esperada.
 *   - NO: decide si el candidato es apto o no (eso es responsabilidad de
 *     src/scoring.js).
 *   - NO: inventa datos que no vinieron en la salida de la IA.
 *
 * Compatible con el nodo "Code" de n8n: sin dependencias externas, se puede
 * pegar tal cual (sin el bloque de exportación de Node) dentro de un nodo
 * Code y llamar a validarExtraccion(...) con la salida del nodo de IA.
 * ============================================================================
 */

// ----------------------------------------------------------------------------
// Esquema esperado (debe mantenerse sincronizado con src/prompt-extraccion.md
// y con NIVELES_EDUCATIVOS en src/scoring.js)
// ----------------------------------------------------------------------------
const CAMPOS_IDENTIDAD = ['nombre', 'email', 'telefono'];
const CAMPOS_EVALUABLES = ['anios_experiencia', 'skills_tecnicas', 'idiomas', 'nivel_educativo'];
// resumen_profesional es texto libre: vive en datos_contexto, NUNCA en
// datos_evaluables (ver nota en la cabecera del archivo).
const CAMPOS_CONTEXTO = ['resumen_profesional'];
const ENUM_NIVELES_EDUCATIVOS = [
  'ninguno',
  'bachillerato',
  'tecnico_tecnologo',
  'tercer_nivel',
  'cuarto_nivel'
];

// ----------------------------------------------------------------------------
// Parseo tolerante de la salida cruda de la IA
// ----------------------------------------------------------------------------

/**
 * Quita los delimitadores de bloque de código Markdown (```json ... ```)
 * que algunos modelos añaden pese a que el prompt los prohíbe
 * explícitamente. Es una capa de tolerancia, no una excusa para relajar el
 * prompt: src/prompt-extraccion.md sigue exigiendo JSON sin markdown.
 * @param {string} texto
 * @returns {string}
 */
function limpiarMarcadoresMarkdown(texto) {
  return texto
    .trim()
    .replace(/^```(json)?/i, '')
    .replace(/```$/, '')
    .trim();
}

/**
 * Intenta obtener un objeto JavaScript a partir de la salida cruda, que
 * puede llegar como string (texto plano del nodo de IA) o ya como objeto
 * (si n8n lo parseó automáticamente).
 * @param {string|object} salidaCruda
 * @returns {{ok: true, valor: object}|{ok: false, error: string}}
 */
function parsearJSON(salidaCruda) {
  if (salidaCruda && typeof salidaCruda === 'object') {
    return { ok: true, valor: salidaCruda };
  }

  if (typeof salidaCruda !== 'string') {
    return {
      ok: false,
      error: `Tipo de dato inesperado en la salida de la IA: se esperaba string u objeto, se recibió "${typeof salidaCruda}".`
    };
  }

  const textoLimpio = limpiarMarcadoresMarkdown(salidaCruda);

  try {
    return { ok: true, valor: JSON.parse(textoLimpio) };
  } catch (error) {
    return {
      ok: false,
      error: `La salida de la IA no es JSON válido: ${error.message}`
    };
  }
}

// ----------------------------------------------------------------------------
// Separación identidad / evaluables / contexto (con reparación defensiva)
// ----------------------------------------------------------------------------

/**
 * Devuelve bruto[clave] si es un objeto plano (no arreglo), o null si no
 * existe o tiene otra forma.
 * @param {object} bruto
 * @param {string} clave
 * @returns {object|null}
 */
function obtenerBloqueONulo(bruto, clave) {
  return bruto[clave] && typeof bruto[clave] === 'object' && !Array.isArray(bruto[clave])
    ? bruto[clave]
    : null;
}

/**
 * Divide el objeto crudo en identidadBruta, evaluablesBrutos y
 * contextoBruto. Si la IA respetó el esquema anidado {datos_identidad,
 * datos_evaluables, datos_contexto}, se usa directamente. Si no (devolvió
 * un objeto plano), se reconstruye la separación a partir de los nombres
 * de campo conocidos, dejando constancia en "errores" de que se tuvo que
 * reparar. Si solo falta "datos_contexto" (identidad y evaluables sí
 * vinieron anidados), se asume resumen_profesional ausente en vez de
 * disparar la reparación completa desde campos planos.
 * @param {object} bruto
 * @param {string[]} errores - arreglo mutable donde se acumulan advertencias
 * @returns {{identidadBruta: object, evaluablesBrutos: object, contextoBruto: object}}
 */
function separarBloques(bruto, errores) {
  const identidadAnidada = obtenerBloqueONulo(bruto, 'datos_identidad');
  const evaluablesAnidados = obtenerBloqueONulo(bruto, 'datos_evaluables');
  const contextoAnidado = obtenerBloqueONulo(bruto, 'datos_contexto');

  if (identidadAnidada && evaluablesAnidados) {
    if (!contextoAnidado) {
      errores.push(
        'La salida de la IA no incluyó el bloque "datos_contexto"; se asume ' +
          'resumen_profesional ausente (null).'
      );
    }
    return {
      identidadBruta: identidadAnidada,
      evaluablesBrutos: evaluablesAnidados,
      contextoBruto: contextoAnidado || {}
    };
  }

  errores.push(
    'La salida de la IA no vino con la estructura anidada {datos_identidad, datos_evaluables, ' +
      'datos_contexto} esperada; se reconstruyó automáticamente a partir de los nombres de campo ' +
      'planos. Si esto ocurre con frecuencia, revisar src/prompt-extraccion.md.'
  );

  const identidadBruta = {};
  const evaluablesBrutos = {};
  const contextoBruto = {};
  CAMPOS_IDENTIDAD.forEach((campo) => {
    identidadBruta[campo] = bruto[campo];
  });
  CAMPOS_EVALUABLES.forEach((campo) => {
    evaluablesBrutos[campo] = bruto[campo];
  });
  CAMPOS_CONTEXTO.forEach((campo) => {
    contextoBruto[campo] = bruto[campo];
  });

  return { identidadBruta, evaluablesBrutos, contextoBruto };
}

// ----------------------------------------------------------------------------
// Normalización de campos individuales
// ----------------------------------------------------------------------------

/**
 * Convierte cualquier valor "vacío" (null, undefined, string en blanco) en
 * null, y todo lo demás en un string recortado. Es la regla base de
 * "rellenar con null en vez de romper".
 * @param {*} valor
 * @returns {string|null}
 */
function normalizarTextoOpcional(valor) {
  if (valor === null || valor === undefined) return null;
  const texto = valor.toString().trim();
  return texto.length > 0 ? texto : null;
}

/**
 * Normaliza un email: recorta espacios, pasa a minúsculas y valida un
 * formato básico. Un email mal formado se descarta (null) y se registra en
 * errores, porque un email inválido rompería silenciosamente los nodos de
 * notificación más adelante en el workflow.
 * @param {*} valor
 * @param {string[]} errores
 * @returns {string|null}
 */
function normalizarEmail(valor, errores) {
  const texto = normalizarTextoOpcional(valor);
  if (texto === null) return null;

  const PATRON_EMAIL_BASICO = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!PATRON_EMAIL_BASICO.test(texto)) {
    errores.push(`El email extraído ("${texto}") no tiene un formato válido; se descarta y se guarda como null.`);
    return null;
  }
  return texto.toLowerCase();
}

/**
 * Normaliza datos_identidad. No se valida "de más" aquí (por ejemplo, no se
 * exige que el nombre tenga cierto formato) porque estos campos NO se usan
 * para tomar decisiones automatizadas, solo para identificar y contactar
 * al candidato.
 * @param {object} identidadBruta
 * @param {string[]} errores
 * @returns {{nombre: string|null, email: string|null, telefono: string|null}}
 */
function normalizarIdentidad(identidadBruta, errores) {
  const fuente = identidadBruta || {};
  return {
    nombre: normalizarTextoOpcional(fuente.nombre),
    email: normalizarEmail(fuente.email, errores),
    telefono: normalizarTextoOpcional(fuente.telefono)
  };
}

/**
 * Normaliza "anios_experiencia" tolerando que la IA lo devuelva como texto
 * ("5", "5 años", "5.5 años de experiencia"). Extrae el primer número que
 * encuentre; si no encuentra ninguno, devuelve null y registra el problema.
 * @param {*} valor
 * @param {string[]} errores
 * @returns {number|null}
 */
function normalizarAniosExperiencia(valor, errores) {
  if (valor === null || valor === undefined || valor === '') return null;

  if (typeof valor === 'number') {
    return Number.isFinite(valor) ? valor : null;
  }

  const coincidencia = valor.toString().match(/\d+(\.\d+)?/);
  if (!coincidencia) {
    errores.push(`No se pudo interpretar "anios_experiencia" (valor recibido: "${valor}"); se guarda como null.`);
    return null;
  }
  return parseFloat(coincidencia[0]);
}

/**
 * Normaliza un campo que debería ser un arreglo de strings (ej.
 * skills_tecnicas). Tolera que la IA devuelva un string separado por comas
 * en vez de un arreglo. Descarta elementos vacíos.
 * @param {*} valor
 * @param {string} nombreCampo - usado solo para mensajes de error
 * @param {string[]} errores
 * @returns {string[]|null}
 */
function normalizarListaTexto(valor, nombreCampo, errores) {
  if (valor === null || valor === undefined) return null;

  let lista;
  if (Array.isArray(valor)) {
    lista = valor;
  } else if (typeof valor === 'string') {
    lista = valor.split(',');
  } else {
    errores.push(`El campo "${nombreCampo}" tiene un tipo inesperado (${typeof valor}); se guarda como null.`);
    return null;
  }

  const limpia = lista
    .map((elemento) => (elemento === null || elemento === undefined ? '' : elemento.toString().trim()))
    .filter((elemento) => elemento.length > 0);

  return limpia.length > 0 ? limpia : null;
}

/**
 * Normaliza el arreglo de idiomas [{idioma, nivel}], descartando entradas
 * malformadas (sin romper el resto del arreglo).
 * @param {*} valor
 * @param {string[]} errores
 * @returns {Array<{idioma: string, nivel: string}>|null}
 */
function normalizarIdiomas(valor, errores) {
  if (valor === null || valor === undefined) return null;
  if (!Array.isArray(valor)) {
    errores.push('El campo "idiomas" debería ser un arreglo; se guarda como null.');
    return null;
  }

  const limpio = [];
  valor.forEach((item, indice) => {
    if (!item || typeof item !== 'object') {
      errores.push(`El idioma en la posición ${indice} no es un objeto {idioma, nivel} válido; se descarta.`);
      return;
    }
    const idioma = normalizarTextoOpcional(item.idioma);
    const nivel = normalizarTextoOpcional(item.nivel);
    if (!idioma || !nivel) {
      errores.push(`El idioma en la posición ${indice} está incompleto (falta "idioma" o "nivel"); se descarta.`);
      return;
    }
    limpio.push({ idioma, nivel });
  });

  return limpio.length > 0 ? limpio : null;
}

/**
 * Normaliza nivel_educativo contra el enum cerrado esperado. Un valor que
 * no coincide con el enum (ej. la IA devolvió "universidad" en vez de
 * "tercer_nivel") se descarta como null en vez de dejarlo pasar como texto
 * libre, porque src/scoring.js necesita un valor del enum para poder
 * ubicarlo en la jerarquía de niveles.
 * @param {*} valor
 * @param {string[]} errores
 * @returns {string|null}
 */
function normalizarNivelEducativo(valor, errores) {
  const texto = normalizarTextoOpcional(valor);
  if (texto === null) return null;

  const normalizado = texto.toLowerCase().replace(/\s+/g, '_');
  if (!ENUM_NIVELES_EDUCATIVOS.includes(normalizado)) {
    errores.push(
      `El nivel educativo recibido ("${valor}") no coincide con el enum esperado ` +
        `(${ENUM_NIVELES_EDUCATIVOS.join(', ')}); se guarda como null.`
    );
    return null;
  }
  return normalizado;
}

/**
 * Normaliza el objeto completo de datos_evaluables. NO incluye
 * resumen_profesional a propósito: ese campo es texto libre y vive en
 * datos_contexto (ver normalizarContexto), nunca en datos_evaluables,
 * porque texto libre puede filtrar identidad sin que el nombre del campo
 * lo delate.
 * @param {object} evaluablesBrutos
 * @param {string[]} errores
 * @returns {object}
 */
function normalizarEvaluables(evaluablesBrutos, errores) {
  const fuente = evaluablesBrutos || {};
  return {
    anios_experiencia: normalizarAniosExperiencia(fuente.anios_experiencia, errores),
    skills_tecnicas: normalizarListaTexto(fuente.skills_tecnicas, 'skills_tecnicas', errores),
    idiomas: normalizarIdiomas(fuente.idiomas, errores),
    nivel_educativo: normalizarNivelEducativo(fuente.nivel_educativo, errores)
  };
}

/**
 * Normaliza datos_contexto: hoy solo contiene resumen_profesional (texto
 * libre para lectura humana del reclutador en Notion). Este bloque nunca
 * se pasa a src/scoring.js.
 * @param {object} contextoBruto
 * @returns {{resumen_profesional: string|null}}
 */
function normalizarContexto(contextoBruto) {
  const fuente = contextoBruto || {};
  return {
    resumen_profesional: normalizarTextoOpcional(fuente.resumen_profesional)
  };
}

// ----------------------------------------------------------------------------
// Función principal
// ----------------------------------------------------------------------------

/**
 * Valida y normaliza la salida cruda del nodo de IA.
 *
 * @param {string|object} salidaCruda - Texto (o objeto ya parseado) devuelto
 *   por el nodo de IA a partir del prompt de extracción.
 *
 * @returns {{
 *   valido: boolean,
 *   datos: {
 *     datos_identidad: {nombre: string|null, email: string|null, telefono: string|null},
 *     datos_evaluables: {
 *       anios_experiencia: number|null,
 *       skills_tecnicas: string[]|null,
 *       idiomas: Array<{idioma:string, nivel:string}>|null,
 *       nivel_educativo: string|null
 *     },
 *     datos_contexto: { resumen_profesional: string|null }
 *   }|null,
 *   errores: string[]
 * }}
 *
 * "valido" es false SOLO cuando la salida ni siquiera pudo interpretarse
 * como un objeto JSON (fallo catastrófico -> revisión manual obligatoria).
 * Con datos parciales o campos malformados, "valido" sigue siendo true pero
 * "errores" queda poblado con cada anomalía encontrada, para trazabilidad;
 * el workflow puede decidir enrutar también a revisión manual si
 * errores.length > 0, según qué tan estricto se quiera ser.
 */
function validarExtraccion(salidaCruda) {
  const resultadoParseo = parsearJSON(salidaCruda);
  if (!resultadoParseo.ok) {
    return { valido: false, datos: null, errores: [resultadoParseo.error] };
  }

  const bruto = resultadoParseo.valor;
  if (!bruto || typeof bruto !== 'object' || Array.isArray(bruto)) {
    return {
      valido: false,
      datos: null,
      errores: ['La salida de la IA debe ser un objeto JSON, no un arreglo ni un valor suelto.']
    };
  }

  const errores = [];
  const { identidadBruta, evaluablesBrutos, contextoBruto } = separarBloques(bruto, errores);

  const datos_identidad = normalizarIdentidad(identidadBruta, errores);
  const datos_evaluables = normalizarEvaluables(evaluablesBrutos, errores);
  const datos_contexto = normalizarContexto(contextoBruto);

  return {
    valido: true,
    datos: { datos_identidad, datos_evaluables, datos_contexto },
    errores
  };
}

// ----------------------------------------------------------------------------
// Exportación
// ----------------------------------------------------------------------------
// Ver la nota equivalente en src/scoring.js: este bloque es inofensivo si se
// pega el archivo dentro de un nodo Code de n8n.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    validarExtraccion,
    // Funciones internas exportadas para pruebas unitarias.
    parsearJSON,
    normalizarIdentidad,
    normalizarEvaluables,
    normalizarContexto,
    normalizarAniosExperiencia,
    normalizarListaTexto,
    normalizarIdiomas,
    normalizarNivelEducativo,
    normalizarEmail,
    ENUM_NIVELES_EDUCATIVOS,
    CAMPOS_IDENTIDAD,
    CAMPOS_EVALUABLES,
    CAMPOS_CONTEXTO
  };
}


/**
 * ============================================================================
 * MOTOR DE SCORING DE CANDIDATOS
 * ============================================================================
 *
 * Sistema Inteligente de Reclutamiento Predictivo - Trabajo de titulación.
 *
 * Este archivo contiene una función PURA (sin efectos secundarios, sin
 * dependencias externas, sin llamadas a red ni a base de datos) que recibe
 * los DATOS EVALUABLES de un candidato (ya extraídos y validados por las
 * capas anteriores del pipeline: nodo de IA + src/validacion.js) y la
 * configuración del puesto vacante, y devuelve un puntaje de 0 a 100 junto
 * con el desglose y las justificaciones de cada punto otorgado.
 *
 * GARANTÍA ARQUITECTÓNICA ANTI-SESGO (separación identidad / datos evaluables)
 * ----------------------------------------------------------------------------
 * El pipeline separa explícitamente, desde la extracción con IA, TRES objetos:
 *
 *   - datos_identidad:  { nombre, email, telefono }
 *   - datos_evaluables: { anios_experiencia, skills_tecnicas, idiomas,
 *                          nivel_educativo }
 *   - datos_contexto:   { resumen_profesional }
 *
 * ESTA función (calcularScore) recibe ÚNICAMENTE "datos_evaluables". Nunca
 * recibe nombre, email, teléfono, ni ningún dato que pudiera revelar género
 * o edad. Esto no es una simple convención de nombres: es una garantía
 * estructural. La función valida en tiempo de ejecución (ver
 * validarSeparacionIdentidad) que ningún campo de identidad se haya colado
 * en los datos evaluables, y si lo detecta, LANZA UNA EXCEPCIÓN en vez de
 * calcular el score. Por lo tanto, es imposible que el motor de scoring
 * discrimine por nombre, género o edad: esos datos jamás llegan a su
 * alcance en tiempo de ejecución, y el código lo verifica activamente en
 * lugar de simplemente "confiar" en que así sea. La reunificación de
 * identidad + score ocurre en una capa posterior (el workflow de n8n o
 * tests/probar-scoring.js), fuera de esta función.
 *
 * POR QUÉ EXISTE "datos_contexto" APARTE DE "datos_evaluables":
 *   resumen_profesional es TEXTO LIBRE generado por la IA a partir del CV.
 *   A diferencia de un campo estructurado como "nombre" o "email", un campo
 *   de texto libre puede contener nombre, edad, género u otras marcas de
 *   identidad sin que su NOMBRE DE CAMPO lo delate (ej. "Ana Lucía Mora,
 *   ingeniera de 34 años, madre de dos hijos" dentro de un campo llamado
 *   "resumen_profesional"). Por eso la garantía anti-sesgo no se limita a
 *   prohibir ciertos nombres de campo: además, resumen_profesional se saca
 *   por completo de datos_evaluables y vive en su propio bloque
 *   (datos_contexto), que solo se usa para registrar en Notion y que un
 *   reclutador humano lo lea — JAMÁS se pasa a calcularScore. Como defensa
 *   adicional en profundidad, "resumen_profesional" y "resumen" también
 *   están en CAMPOS_IDENTIDAD_PROHIBIDOS: si por error alguien igual lo
 *   pasara dentro de datos_evaluables, la guardia lo rechaza igual.
 *
 * DISEÑO PENSADO PARA SER DEFENDIBLE ANTE UN TRIBUNAL:
 *   - Cada categoría tiene un peso máximo fijo y documentado.
 *   - Cada punto sumado o restado genera una justificación legible.
 *   - No hay aleatoriedad ni llamadas a IA en este archivo: dado el mismo
 *     perfil y la misma configuración, el resultado SIEMPRE es el mismo
 *     (determinismo = trazabilidad).
 *   - Compatible con el nodo "Code" de n8n: se puede pegar tal cual el
 *     cuerpo de este archivo (sin el bloque de exportación de Node) dentro
 *     de un nodo Code y llamar a calcularScore(...) con los datos del item.
 *
 * DISTRIBUCIÓN DE PUNTAJE (suma = 100, VERIFICADA en tiempo de ejecución
 * por validarPesosCategorias, no solo documentada):
 *   - Skills técnicas .......... 40 pts
 *   - Experiencia laboral ....... 30 pts
 *   - Nivel educativo ........... 20 pts
 *   - Idiomas ................... 10 pts
 *
 * IMPORTANTE sobre config/puestos.json (INVARIANTE VERIFICADA, no una mera
 * convención): la suma de los "peso" de skills_obligatorias +
 * skills_deseables DEBE ser igual a PESO_SKILLS (40). validarEntradas() lo
 * comprueba en cada llamada a calcularScore y lanza una excepción si no se
 * cumple — así un config/puestos.json mal editado (ej. pesos que suman 85)
 * no puede producir silenciosamente un score fuera de 0-100. El ejemplo de
 * config/puestos.json ya cumple esto (30 obligatorias + 10 deseables = 40).
 * ============================================================================
 */

// ----------------------------------------------------------------------------
// Pesos máximos por categoría (deben sumar 100)
// ----------------------------------------------------------------------------
const PESO_SKILLS = 40;
const PESO_EXPERIENCIA = 30;
const PESO_EDUCACION = 20;
const PESO_IDIOMAS = 10;

// Jerarquía de niveles educativos, de menor a mayor.
// Se usa por índice: a mayor índice, mayor nivel educativo.
const NIVELES_EDUCATIVOS = [
  'ninguno',
  'bachillerato',
  'tecnico_tecnologo',
  'tercer_nivel',
  'cuarto_nivel'
];

// Escala CEFR (Common European Framework of Reference) para idiomas,
// de menor a mayor dominio.
const NIVELES_CEFR = ['a1', 'a2', 'b1', 'b2', 'c1', 'c2'];

// ----------------------------------------------------------------------------
// Utilidades de normalización y redondeo
// ----------------------------------------------------------------------------

/**
 * Normaliza un texto para comparaciones tolerantes a mayúsculas, tildes,
 * espacios y separadores. Así "Node.js", "NodeJS" y "node js" se consideran
 * el mismo valor tras normalizar ("nodejs").
 * @param {string} texto
 * @returns {string} texto normalizado en minúsculas, sin tildes ni símbolos
 */
function normalizarTexto(texto) {
  if (texto === null || texto === undefined) return '';

  // NFD descompone los caracteres acentuados en (letra base + marca de
  // acento independiente). Por ejemplo "e" + "´" en vez de "é".
  const descompuesto = texto.toString().toLowerCase().normalize('NFD');

  // Las marcas de acento combinantes (tildes, diéresis, virgulillas, etc.)
  // ocupan los códigos Unicode 768 a 879 (bloque "Combining Diacritical
  // Marks"). Se filtran carácter por carácter para eliminarlas sin
  // depender de literales Unicode dentro del código fuente.
  const COMBINACION_DIACRITICA_INICIO = 768;
  const COMBINACION_DIACRITICA_FIN = 879;
  let sinTildes = '';
  for (const caracter of descompuesto) {
    const codigo = caracter.codePointAt(0);
    const esDiacritico = codigo >= COMBINACION_DIACRITICA_INICIO && codigo <= COMBINACION_DIACRITICA_FIN;
    if (!esDiacritico) sinTildes += caracter;
  }

  return sinTildes.replace(/[^a-z0-9]/g, ''); // elimina espacios, puntos, guiones, etc.
}

/**
 * Redondea a 2 decimales para evitar arrastrar errores de coma flotante
 * en los reportes (ej. 23.240000000000002 -> 23.24).
 * @param {number} numero
 * @returns {number}
 */
function round2(numero) {
  return Math.round(numero * 100) / 100;
}

/**
 * Verifica si el candidato posee una skill específica, comparando de forma
 * normalizada (case-insensitive, tolerante a variantes de escritura) contra
 * el "nombre" de la skill requerida Y, si está configurado, contra sus
 * "sinonimos" (ej. la skill requerida "SQL" con sinonimos ["PostgreSQL",
 * "MySQL", ...] hace match si el candidato declaró "PostgreSQL").
 *
 * El campo "sinonimos" en config/puestos.json es OPCIONAL: una skill sin
 * ese campo se compara únicamente por "nombre", exactamente igual que
 * antes de que existiera esta función de equivalencias (retrocompatible).
 *
 * TRAZABILIDAD: se prueba primero el nombre exacto y solo si falla se
 * recorren los sinónimos, en el mismo orden en que aparecen en
 * config/puestos.json. Se devuelve el término TAL COMO LO ESCRIBIÓ EL
 * CANDIDATO (no el sinónimo de la lista de configuración), para poder
 * citar en la justificación exactamente qué dijo el CV que motivó el
 * punto otorgado.
 *
 * LIMITACIÓN CONOCIDA (ver README): esta es una equivalencia LÉXICA
 * (comparación de strings normalizados contra una lista fija), no
 * semántica. No infiere por sí sola que "PostgreSQL" implica "SQL"; solo
 * lo reconoce si "PostgreSQL" está explícitamente en la lista de
 * sinónimos que el reclutador configuró para esa skill.
 *
 * @param {string[]} skillsCandidato
 * @param {{nombre: string, peso: number, sinonimos?: string[]}} skillRequerida
 * @returns {{coincide: boolean, terminoCandidato: string|null, fueSinonimo: boolean}}
 */
function candidatoTieneSkill(skillsCandidato, skillRequerida) {
  const candidatos = skillsCandidato || [];

  const nombreNormalizado = normalizarTexto(skillRequerida.nombre);
  const matchPorNombre = candidatos.find((s) => normalizarTexto(s) === nombreNormalizado);
  if (matchPorNombre !== undefined) {
    return { coincide: true, terminoCandidato: matchPorNombre, fueSinonimo: false };
  }

  const sinonimos = skillRequerida.sinonimos || [];
  for (const sinonimo of sinonimos) {
    const sinonimoNormalizado = normalizarTexto(sinonimo);
    const matchPorSinonimo = candidatos.find((s) => normalizarTexto(s) === sinonimoNormalizado);
    if (matchPorSinonimo !== undefined) {
      return { coincide: true, terminoCandidato: matchPorSinonimo, fueSinonimo: true };
    }
  }

  return { coincide: false, terminoCandidato: null, fueSinonimo: false };
}

/**
 * Devuelve el índice de un nivel CEFR normalizado, o -1 si no es reconocible.
 * @param {string} nivel
 * @returns {number}
 */
function indiceCEFR(nivel) {
  if (!nivel) return -1;
  return NIVELES_CEFR.indexOf(normalizarTexto(nivel));
}

// ----------------------------------------------------------------------------
// Validación de entradas (falla rápido y con mensajes claros)
// ----------------------------------------------------------------------------

// Campos que NUNCA deben aparecer dentro de datos_evaluables. Si alguno de
// estos aparece, significa que la capa de validación (src/validacion.js) no
// separó correctamente identidad de datos evaluables, y es un error grave
// de arquitectura, no un dato faltante: por eso se lanza excepción en vez
// de simplemente ignorarlo.
const CAMPOS_IDENTIDAD_PROHIBIDOS = [
  'nombre',
  'email',
  'telefono',
  'genero',
  'sexo',
  'edad',
  'fecha_nacimiento',
  // Texto libre: puede contener nombre, edad o marcas de género sin que el
  // NOMBRE del campo lo delate (ver "POR QUÉ EXISTE datos_contexto" en la
  // cabecera del archivo). Vive en datos_contexto, nunca en datos_evaluables.
  'resumen_profesional',
  'resumen'
];

/**
 * Verifica activamente que ningún campo de identidad se haya colado dentro
 * de datos_evaluables. Esta función es la que hace CUMPLIR en tiempo de
 * ejecución la garantía anti-sesgo descrita en la cabecera del archivo: no
 * basta con documentar la separación, hay que verificarla.
 * @param {object} datosEvaluables
 */
function validarSeparacionIdentidad(datosEvaluables) {
  const camposEncontrados = CAMPOS_IDENTIDAD_PROHIBIDOS.filter((campo) =>
    Object.prototype.hasOwnProperty.call(datosEvaluables, campo)
  );

  if (camposEncontrados.length > 0) {
    throw new Error(
      `calcularScore: se detectaron campos de identidad (${camposEncontrados.join(', ')}) ` +
        'dentro de datos_evaluables. Esto viola la garantía arquitectónica anti-sesgo: el ' +
        'motor de scoring nunca debe recibir datos que permitan discriminar por nombre, ' +
        'género o edad. Revisar la capa de validación (src/validacion.js), responsable de ' +
        'separar datos_identidad de datos_evaluables antes de llegar aquí.'
    );
  }
}

/**
 * Verifica que la suma de pesos de skills_obligatorias + skills_deseables en
 * config/puestos.json sea exactamente PESO_SKILLS (40). Sin este chequeo, un
 * config/puestos.json editado a mano con pesos que suman, por ejemplo, 85,
 * haría que calcularScore devolviera un score_total mayor a 100 y un
 * desglose autocontradictorio (ej. {"puntos":85,"maximo":40}). Es una
 * INVARIANTE VERIFICADA en cada llamada, no una convención que se confía
 * que el autor del config respetó.
 * @param {object} configPuesto
 */
function validarPesosSkills(configPuesto) {
  const sumaObligatorias = (configPuesto.skills_obligatorias || []).reduce(
    (acumulado, skill) => acumulado + skill.peso,
    0
  );
  const sumaDeseables = (configPuesto.skills_deseables || []).reduce(
    (acumulado, skill) => acumulado + skill.peso,
    0
  );
  const sumaTotal = round2(sumaObligatorias + sumaDeseables);

  if (sumaTotal !== PESO_SKILLS) {
    throw new Error(
      `calcularScore: la suma de pesos de skills_obligatorias + skills_deseables en ` +
        `config/puestos.json es ${sumaTotal}, pero debe ser exactamente ${PESO_SKILLS} ` +
        '(PESO_SKILLS). Revisar config/puestos.json y ajustar los "peso" de cada skill hasta ' +
        `que la suma total dé ${PESO_SKILLS}.`
    );
  }
}

/**
 * Verifica que los pesos máximos por categoría (constantes al inicio de
 * este archivo) sumen 100. Es una invariante del propio código fuente, no
 * de config/puestos.json, pero se comprueba en cada llamada junto con las
 * demás invariantes para detectar de inmediato un error de edición en las
 * constantes PESO_* si alguna vez alguien las modifica sin actualizar las
 * demás.
 */
function validarPesosCategorias() {
  const sumaCategorias = PESO_SKILLS + PESO_EXPERIENCIA + PESO_EDUCACION + PESO_IDIOMAS;
  if (sumaCategorias !== 100) {
    throw new Error(
      'calcularScore: la suma de los pesos máximos por categoría (PESO_SKILLS + ' +
        `PESO_EXPERIENCIA + PESO_EDUCACION + PESO_IDIOMAS) es ${sumaCategorias}, pero debe ser ` +
        'exactamente 100. Revisar las constantes PESO_* al inicio de src/scoring.js.'
    );
  }
}

/**
 * Valida que datosEvaluables y configPuesto tengan la forma mínima esperada.
 * Se valida estrictamente la CONFIGURACIÓN (porque un error ahí afecta a
 * todos los candidatos), pero se es tolerante con los campos evaluables del
 * candidato (porque pueden venir null si el CV no los menciona; ver cada
 * función de cálculo para el manejo de nulos). También se hace cumplir la
 * separación identidad / datos evaluables (ver validarSeparacionIdentidad)
 * y las invariantes de pesos (ver validarPesosSkills y
 * validarPesosCategorias).
 * @param {object} datosEvaluables
 * @param {object} configPuesto
 */
function validarEntradas(datosEvaluables, configPuesto) {
  if (!datosEvaluables || typeof datosEvaluables !== 'object') {
    throw new Error(
      'calcularScore: "datosEvaluables" debe ser un objeto. Revisar la salida de src/validacion.js.'
    );
  }
  if (!configPuesto || typeof configPuesto !== 'object') {
    throw new Error(
      'calcularScore: "configPuesto" debe ser un objeto. Revisar config/puestos.json.'
    );
  }

  validarSeparacionIdentidad(datosEvaluables);

  const camposRequeridos = [
    'skills_obligatorias',
    'skills_deseables',
    'experiencia_minima_anios',
    'experiencia_ideal_anios',
    'nivel_educativo_requerido',
    'idiomas_requeridos',
    'umbrales'
  ];

  camposRequeridos.forEach((campo) => {
    if (configPuesto[campo] === undefined) {
      throw new Error(
        `calcularScore: configPuesto.${campo} es obligatorio y no fue encontrado. Revisar config/puestos.json.`
      );
    }
  });

  validarPesosSkills(configPuesto);
  validarPesosCategorias();
}

// ----------------------------------------------------------------------------
// Categoría 1: Skills técnicas (máx. 40 pts)
// ----------------------------------------------------------------------------

/**
 * Calcula el puntaje de skills técnicas comparando las skills del candidato
 * contra las obligatorias y deseables del puesto. Cada skill otorga sus
 * propios puntos ("peso") definidos en config/puestos.json si el candidato
 * la posee (por nombre exacto o por un sinónimo configurado, ver
 * candidatoTieneSkill); si no la posee, no suma (no hay puntos negativos).
 * @param {object} datosEvaluables
 * @param {object} config
 * @returns {{puntos: number, justificaciones: string[]}}
 */
function calcularSkills(datosEvaluables, config) {
  const justificaciones = [];
  let puntos = 0;
  const skillsCandidato = datosEvaluables.skills_tecnicas || [];

  (config.skills_obligatorias || []).forEach((skill) => {
    const resultado = candidatoTieneSkill(skillsCandidato, skill);
    if (resultado.coincide) {
      puntos += skill.peso;
      if (resultado.fueSinonimo) {
        justificaciones.push(
          `Cumple skill obligatoria "${skill.nombre}" por equivalencia con "${resultado.terminoCandidato}": +${skill.peso} pts`
        );
      } else {
        justificaciones.push(`Cumple skill obligatoria "${skill.nombre}": +${skill.peso} pts`);
      }
    } else {
      justificaciones.push(
        `No cumple skill obligatoria "${skill.nombre}": +0 pts (máx ${skill.peso})`
      );
    }
  });

  (config.skills_deseables || []).forEach((skill) => {
    const resultado = candidatoTieneSkill(skillsCandidato, skill);
    if (resultado.coincide) {
      puntos += skill.peso;
      if (resultado.fueSinonimo) {
        justificaciones.push(
          `Cumple skill deseable "${skill.nombre}" por equivalencia con "${resultado.terminoCandidato}": +${skill.peso} pts`
        );
      } else {
        justificaciones.push(`Cumple skill deseable "${skill.nombre}": +${skill.peso} pts`);
      }
    } else {
      justificaciones.push(
        `No cumple skill deseable "${skill.nombre}": +0 pts (máx ${skill.peso})`
      );
    }
  });

  return { puntos: round2(puntos), justificaciones };
}

// ----------------------------------------------------------------------------
// Categoría 2: Experiencia laboral (máx. 30 pts)
// ----------------------------------------------------------------------------

/**
 * Calcula el puntaje de experiencia usando una curva de raíz cuadrada con
 * tope (nunca lineal infinita): los primeros años de experiencia suman
 * proporcionalmente más que los últimos, y el puntaje se satura en 30 pts
 * al alcanzar (o superar) experiencia_ideal_anios.
 *
 * Fórmula: puntos = PESO_EXPERIENCIA * sqrt(min(anios / ideal, 1))
 *
 * Si el candidato no alcanza el mínimo requerido (experiencia_minima_anios),
 * se aplica un factor de penalización adicional, porque no cumplir el
 * mínimo es cualitativamente distinto a simplemente tener menos años que
 * el ideal.
 *
 * @param {number|null} aniosExperiencia
 * @param {object} config
 * @returns {{puntos: number, justificacion: string}}
 */
function calcularExperiencia(aniosExperiencia, config) {
  const { experiencia_minima_anios: minima, experiencia_ideal_anios: ideal } = config;

  if (aniosExperiencia === null || aniosExperiencia === undefined || isNaN(aniosExperiencia)) {
    return {
      puntos: 0,
      justificacion: `Años de experiencia no especificados en el CV: +0 pts (máx ${PESO_EXPERIENCIA})`
    };
  }

  const ratio = Math.min(aniosExperiencia / ideal, 1);
  let puntos = PESO_EXPERIENCIA * Math.sqrt(ratio);

  let notaPenalizacion = '';
  if (aniosExperiencia < minima) {
    const FACTOR_PENALIZACION = 0.6; // no cumplir el mínimo es más grave que solo tener menos años
    puntos *= FACTOR_PENALIZACION;
    notaPenalizacion = `, por debajo del mínimo de ${minima} años (factor de penalización x${FACTOR_PENALIZACION})`;
  }

  puntos = round2(puntos);

  return {
    puntos,
    justificacion: `Experiencia: ${aniosExperiencia} años (ideal: ${ideal} años)${notaPenalizacion}: +${puntos} pts (máx ${PESO_EXPERIENCIA})`
  };
}

// ----------------------------------------------------------------------------
// Categoría 3: Nivel educativo (máx. 20 pts)
// ----------------------------------------------------------------------------

/**
 * Calcula el puntaje educativo comparando el nivel del candidato contra el
 * nivel requerido en una jerarquía ordenada (NIVELES_EDUCATIVOS). Superar
 * el nivel requerido no otorga puntos extra (el máximo sigue siendo 20),
 * pero sí se documenta en la justificación.
 * @param {object} datosEvaluables
 * @param {object} config
 * @returns {{puntos: number, justificaciones: string[]}}
 */
function calcularEducacion(datosEvaluables, config) {
  const requerido = config.nivel_educativo_requerido;
  const candidatoNivel = datosEvaluables.nivel_educativo;

  const idxRequerido = NIVELES_EDUCATIVOS.indexOf(requerido);
  const idxCandidato = NIVELES_EDUCATIVOS.indexOf(normalizarNivelEducativo(candidatoNivel));

  if (candidatoNivel === null || candidatoNivel === undefined || idxCandidato === -1) {
    return {
      puntos: 0,
      justificaciones: [
        `Nivel educativo no especificado o no reconocible en el CV: +0 pts (máx ${PESO_EDUCACION})`
      ]
    };
  }

  const diferencia = idxCandidato - idxRequerido;
  let puntos;
  let detalle;

  if (diferencia >= 1) {
    puntos = PESO_EDUCACION;
    detalle = 'supera el nivel requerido';
  } else if (diferencia === 0) {
    puntos = PESO_EDUCACION;
    detalle = 'cumple exactamente el nivel requerido';
  } else if (diferencia === -1) {
    puntos = PESO_EDUCACION * 0.5;
    detalle = 'un nivel por debajo del requerido';
  } else {
    puntos = 0;
    detalle = 'muy por debajo del nivel requerido';
  }

  puntos = round2(puntos);

  return {
    puntos,
    justificaciones: [
      `Educación: "${candidatoNivel}" vs "${requerido}" requerido (${detalle}): +${puntos} pts (máx ${PESO_EDUCACION})`
    ]
  };
}

/**
 * Normaliza el nivel educativo del candidato para tolerar variantes de
 * escritura (mayúsculas, guiones bajos vs espacios) antes de buscarlo en
 * NIVELES_EDUCATIVOS. Se espera que el nodo de IA ya devuelva uno de los
 * valores del enum definido en prompt-extraccion.md, pero esta función
 * añade una capa extra de tolerancia.
 * @param {string|null} nivel
 * @returns {string}
 */
function normalizarNivelEducativo(nivel) {
  if (!nivel) return '';
  return nivel.toString().trim().toLowerCase().replace(/\s+/g, '_');
}

// ----------------------------------------------------------------------------
// Categoría 4: Idiomas (máx. 10 pts)
// ----------------------------------------------------------------------------

/**
 * Calcula el puntaje de idiomas repartiendo PESO_IDIOMAS equitativamente
 * entre los idiomas requeridos por el puesto. Para cada idioma requerido:
 *   - Si el candidato no lo declara: 0 pts para ese idioma.
 *   - Si lo declara con nivel >= al mínimo (escala CEFR): puntos completos.
 *   - Si lo declara con nivel < al mínimo: puntos proporcionales al nivel
 *     alcanzado (nunca negativo), para no penalizar por igual a alguien
 *     con A2 que a alguien con B1 cuando ambos están por debajo de B2.
 * @param {object} datosEvaluables
 * @param {object} config
 * @returns {{puntos: number, justificaciones: string[]}}
 */
function calcularIdiomas(datosEvaluables, config) {
  const requeridos = config.idiomas_requeridos || [];

  if (requeridos.length === 0) {
    // DECISIÓN DE DISEÑO (intencional, no un caso sin cubrir): si el puesto
    // no exige ningún idioma, el candidato recibe los PESO_IDIOMAS puntos
    // completos en vez de 0. No tendría sentido penalizar a un candidato
    // por no acreditar un idioma que el puesto nunca pidió; el máximo de la
    // categoría representa "cumple con lo que el puesto exige en idiomas",
    // y si no exige nada, se cumple trivialmente. Ver también README,
    // sección "Configuración del puesto".
    return {
      puntos: PESO_IDIOMAS,
      justificaciones: [`No se exigen idiomas para este puesto: +${PESO_IDIOMAS} pts (máx ${PESO_IDIOMAS})`]
    };
  }

  const pesoPorIdioma = round2(PESO_IDIOMAS / requeridos.length);
  const idiomasCandidato = datosEvaluables.idiomas || [];
  const justificaciones = [];
  let puntosTotales = 0;

  requeridos.forEach((req) => {
    const nombreNormalizado = normalizarTexto(req.idioma);
    const encontrado = idiomasCandidato.find(
      (i) => normalizarTexto(i.idioma) === nombreNormalizado
    );

    if (!encontrado) {
      justificaciones.push(
        `No acredita idioma "${req.idioma}" (mínimo ${req.nivel_minimo}): +0 pts (máx ${pesoPorIdioma})`
      );
      return;
    }

    const idxRequerido = indiceCEFR(req.nivel_minimo);
    const idxCandidato = indiceCEFR(encontrado.nivel);

    if (idxCandidato === -1) {
      justificaciones.push(
        `Idioma "${req.idioma}" declarado pero con nivel no reconocible ("${encontrado.nivel}"): +0 pts (máx ${pesoPorIdioma})`
      );
      return;
    }

    if (idxCandidato >= idxRequerido) {
      puntosTotales += pesoPorIdioma;
      justificaciones.push(
        `Cumple idioma "${req.idioma}" en nivel ${encontrado.nivel} (mínimo ${req.nivel_minimo}): +${pesoPorIdioma} pts`
      );
    } else {
      // Puntaje proporcional a qué tan cerca está del nivel mínimo exigido.
      const ratio = (idxCandidato + 1) / (idxRequerido + 1);
      const parcial = round2(pesoPorIdioma * ratio);
      puntosTotales += parcial;
      justificaciones.push(
        `Idioma "${req.idioma}" en nivel ${encontrado.nivel}, por debajo del mínimo ${req.nivel_minimo}: +${parcial} pts (máx ${pesoPorIdioma})`
      );
    }
  });

  return { puntos: round2(puntosTotales), justificaciones };
}

// ----------------------------------------------------------------------------
// Función principal
// ----------------------------------------------------------------------------

/**
 * Calcula el score final (0-100) de un candidato para un puesto dado,
 * junto con el desglose por categoría y las justificaciones legibles de
 * cada punto otorgado o no otorgado.
 *
 * IMPORTANTE (garantía anti-sesgo): esta función recibe ÚNICAMENTE
 * datos_evaluables. NO recibe ni devuelve nombre, email, teléfono ni
 * ningún otro dato de identidad — ver la cabecera de este archivo. La
 * capa que llama a calcularScore (el workflow de n8n o
 * tests/probar-scoring.js) es responsable de reunificar este resultado
 * con datos_identidad para efectos de reporte y notificación.
 *
 * @param {object} datosEvaluables - Datos evaluables extraídos y validados del CV
 * @param {number|null} datosEvaluables.anios_experiencia
 * @param {string[]|null} datosEvaluables.skills_tecnicas
 * @param {Array<{idioma:string, nivel:string}>|null} datosEvaluables.idiomas
 * @param {string|null} datosEvaluables.nivel_educativo
 *
 * @param {object} configPuesto - Configuración del puesto (ver config/puestos.json)
 *
 * @returns {{
 *   score_total: number,
 *   clasificacion: 'ENTREVISTA'|'REVISION'|'RECHAZO',
 *   desglose: {
 *     skills: {puntos: number, maximo: number},
 *     experiencia: {puntos: number, maximo: number},
 *     educacion: {puntos: number, maximo: number},
 *     idiomas: {puntos: number, maximo: number}
 *   },
 *   justificaciones: string[]
 * }}
 */
function calcularScore(datosEvaluables, configPuesto) {
  validarEntradas(datosEvaluables, configPuesto);

  const resultadoSkills = calcularSkills(datosEvaluables, configPuesto);
  const resultadoExperiencia = calcularExperiencia(datosEvaluables.anios_experiencia, configPuesto);
  const resultadoEducacion = calcularEducacion(datosEvaluables, configPuesto);
  const resultadoIdiomas = calcularIdiomas(datosEvaluables, configPuesto);

  const scoreTotal = round2(
    resultadoSkills.puntos +
      resultadoExperiencia.puntos +
      resultadoEducacion.puntos +
      resultadoIdiomas.puntos
  );

  const justificaciones = [
    ...resultadoSkills.justificaciones,
    resultadoExperiencia.justificacion,
    ...resultadoEducacion.justificaciones,
    ...resultadoIdiomas.justificaciones
  ];

  const umbrales = configPuesto.umbrales;
  let clasificacion;
  if (scoreTotal >= umbrales.entrevista) {
    clasificacion = 'ENTREVISTA';
  } else if (scoreTotal >= umbrales.revision) {
    clasificacion = 'REVISION';
  } else {
    clasificacion = 'RECHAZO';
  }

  return {
    score_total: scoreTotal,
    clasificacion,
    desglose: {
      skills: { puntos: resultadoSkills.puntos, maximo: PESO_SKILLS },
      experiencia: { puntos: resultadoExperiencia.puntos, maximo: PESO_EXPERIENCIA },
      educacion: { puntos: resultadoEducacion.puntos, maximo: PESO_EDUCACION },
      idiomas: { puntos: resultadoIdiomas.puntos, maximo: PESO_IDIOMAS }
    },
    justificaciones
  };
}

// ----------------------------------------------------------------------------
// Exportación
// ----------------------------------------------------------------------------
// Este bloque solo se ejecuta en un entorno Node.js (como el nodo Code de
// n8n o el script de pruebas tests/probar-scoring.js). Si se pega el
// contenido de este archivo directamente dentro de un nodo Code de n8n,
// este bloque es inofensivo: simplemente no hace nada si "module" no
// existe en el contexto de ejecución.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    calcularScore,
    // Se exportan también las funciones internas para poder probarlas de
    // forma unitaria si el tribunal o un futuro mantenedor lo requiere.
    calcularSkills,
    candidatoTieneSkill,
    calcularExperiencia,
    calcularEducacion,
    calcularIdiomas,
    normalizarTexto,
    validarSeparacionIdentidad,
    validarPesosSkills,
    validarPesosCategorias,
    CAMPOS_IDENTIDAD_PROHIBIDOS,
    PESO_SKILLS,
    PESO_EXPERIENCIA,
    PESO_EDUCACION,
    PESO_IDIOMAS
  };
}


/**
 * ============================================================================
 * SELECCIÓN DE PUESTO VACANTE
 * ============================================================================
 *
 * Sistema Inteligente de Reclutamiento Predictivo - Trabajo de titulación.
 *
 * El sistema soporta VARIOS puestos vacantes simultáneos, configurados en
 * `config/puestos.json` como un arreglo. El candidato elige uno en el
 * campo "Puesto al que postula" del formulario (un desplegable generado
 * dinámicamente a partir de ese mismo arreglo, ver
 * scripts/generar-workflow.js), y este archivo es responsable de resolver
 * ese texto elegido a la configuración de puesto correspondiente.
 *
 * REGLA DE ORO: si el puesto que llega del formulario NO coincide con
 * ningún puesto configurado, NUNCA se debe calificar al candidato contra
 * un puesto por defecto o "el primero de la lista". Calificar a alguien
 * contra los requisitos de un puesto que no pidió sería un error grave en
 * un sistema que se presenta como auditable ante un tribunal: el
 * candidato terminaría siendo evaluado, aceptado o rechazado con
 * criterios que no corresponden a la vacante real. Por eso
 * seleccionarPuesto() nunca inventa una configuración por defecto: si no
 * encuentra coincidencia, lo señala explícitamente para que el workflow
 * enrute el caso a revisión manual en vez de calcular un score.
 *
 * Compatible con el nodo "Code" de n8n: sin dependencias externas, se
 * puede pegar tal cual (sin el bloque de exportación de Node) dentro de un
 * nodo Code y llamar a seleccionarPuesto(...) con el arreglo de puestos y
 * el título que el candidato eligió en el formulario.
 * ============================================================================
 */

/**
 * Busca, dentro del arreglo de puestos de config/puestos.json, el que
 * coincide EXACTAMENTE (salvo espacios sobrantes al inicio/fin) con el
 * título recibido del formulario. No se usa comparación insensible a
 * mayúsculas ni tolerante a variantes: el campo del formulario es un
 * desplegable de opciones cerradas generado a partir de los mismos
 * títulos, así que un candidato nunca "escribe" el puesto — lo elige de
 * una lista. Un desajuste indica un problema de configuración (ej. se
 * regeneró el workflow con un config/puestos.json distinto al que estaba
 * activo cuando se completó el formulario), no una variante de escritura
 * a tolerar.
 *
 * @param {Array<object>} puestos - arreglo de configuraciones de puesto
 *   (la forma de config/puestos.json: { puestos: [...] }.puestos)
 * @param {string} tituloSolicitado - el valor exacto del campo "Puesto al
 *   que postula" tal como llegó del Form Trigger
 * @returns {
 *   {encontrado: true, configPuesto: object, motivo: null} |
 *   {encontrado: false, configPuesto: null, motivo: string}
 * }
 */
function seleccionarPuesto(puestos, tituloSolicitado) {
  if (!Array.isArray(puestos) || puestos.length === 0) {
    return {
      encontrado: false,
      configPuesto: null,
      motivo: 'config/puestos.json no contiene un arreglo "puestos" válido o está vacío.'
    };
  }

  const tituloNormalizado = (tituloSolicitado || '').toString().trim();

  if (tituloNormalizado.length === 0) {
    return {
      encontrado: false,
      configPuesto: null,
      motivo: 'El formulario no trajo ningún valor en "Puesto al que postula".'
    };
  }

  const configPuesto = puestos.find((puesto) => puesto.titulo === tituloNormalizado);

  if (!configPuesto) {
    return {
      encontrado: false,
      configPuesto: null,
      motivo: `El puesto "${tituloNormalizado}" no está configurado en config/puestos.json.`
    };
  }

  return { encontrado: true, configPuesto, motivo: null };
}

// ----------------------------------------------------------------------------
// Exportación
// ----------------------------------------------------------------------------
// Ver la nota equivalente en src/scoring.js: este bloque es inofensivo si se
// pega el archivo dentro de un nodo Code de n8n.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { seleccionarPuesto };
}


